(function(){
// İndirme düğmelerini kaldır; oynatılan kayıt tarayıcı önbelleğinden yeniden kullanılabilir.
$('download-arabic')?.remove();
$('download-turkish')?.remove();
const audioNote=$('audio-panel')?.querySelector('small');if(audioNote)audioNote.textContent='Arapça: seçtiğiniz kârînin tam sure kaydı. Türkçe: Türkiye Diyanet Vakfı tarafından hazırlanmış insan sesli meal kaydı.';

// Her ayetin altında ortak oynatıcıyı yöneten erişilebilir kontroller.
function formatTime(value){if(!Number.isFinite(value))return '0:00';const m=Math.floor(value/60),s=Math.floor(value%60);return `${m}:${String(s).padStart(2,'0')}`;}
function addInlinePlayers(){document.querySelectorAll('#verses .verse').forEach(card=>{if(card.querySelector('.verse-inline-player'))return;const bar=document.createElement('div');bar.className='verse-inline-player';bar.innerHTML='<button type="button" class="inline-toggle" aria-label="Oynat veya duraklat">▶</button><span class="inline-time">0:00 / 0:00</span><input class="inline-seek" type="range" min="0" max="1000" value="0" aria-label="Ses konumu"><select class="inline-speed" aria-label="Oynatma hızı"><option value="0.75">0,75×</option><option value="1" selected>1×</option><option value="1.25">1,25×</option><option value="1.5">1,5×</option><option value="2">2×</option></select><span class="volume-icon">🔊</span><input class="inline-volume" type="range" min="0" max="1" step="0.05" value="1" aria-label="Ses düzeyi">';card.append(bar);});}
const previousRenderReader=renderReader;renderReader=function(target){previousRenderReader(target);addInlinePlayers();};addInlinePlayers();
const player=$('quran-audio');
function activeBar(){return document.querySelector('#verses .verse.is-playing .verse-inline-player');}
player?.addEventListener('play',()=>{document.querySelectorAll('.inline-toggle').forEach(x=>x.textContent='▶');const b=activeBar()?.querySelector('.inline-toggle');if(b)b.textContent='❚❚';});
player?.addEventListener('pause',()=>{const b=activeBar()?.querySelector('.inline-toggle');if(b)b.textContent='▶';});
player?.addEventListener('timeupdate',()=>{const bar=activeBar();if(!bar)return;const duration=player.duration||0;bar.querySelector('.inline-time').textContent=`${formatTime(player.currentTime)} / ${formatTime(duration)}`;bar.querySelector('.inline-seek').value=duration?Math.round(player.currentTime/duration*1000):0;bar.querySelector('.inline-toggle').textContent=player.paused?'▶':'❚❚';});
$('verses')?.addEventListener('input',event=>{const seek=event.target.closest('.inline-seek'),volume=event.target.closest('.inline-volume');if(seek&&player?.duration)player.currentTime=Number(seek.value)/1000*player.duration;if(volume)player.volume=Number(volume.value);});
$('verses')?.addEventListener('change',event=>{const speed=event.target.closest('.inline-speed');if(speed&&player)player.playbackRate=Number(speed.value);});
$('verses')?.addEventListener('click',event=>{const toggle=event.target.closest('.inline-toggle');if(!toggle)return;event.preventDefault();const card=toggle.closest('.verse');if(card.classList.contains('is-playing')&&player.src){player.paused?player.play():player.pause();return;}card.querySelector('[data-play-ayah]')?.click();},true);

// Kur’an Yolu tefsirlerini uygulama içinde göster.
let tafsirPromise;
function loadTafsir(){return tafsirPromise||(tafsirPromise=fetch('/tefsir.json').then(r=>{if(!r.ok)throw new Error('Tefsir verisi yüklenemedi');return r.json();}));}
$('verses')?.addEventListener('click',async event=>{const button=event.target.closest('[data-tafsir]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const box=button.nextElementSibling;if(!box)return;if(!box.hidden){box.hidden=true;button.textContent='Tefsiri göster';return;}box.hidden=false;button.textContent='Tefsiri gizle';box.innerHTML='<strong>Kur’an Yolu Tefsiri</strong><p>Tefsir hazırlanıyor…</p>';try{const data=await loadTafsir(),surah=data.find(x=>Number(x.sureID)===state.selected),ayah=Number(button.dataset.tafsir),entry=surah?.tefsirler?.find(x=>x.ayetler?.map(Number).includes(ayah));box.innerHTML=`<strong>Kur’an Yolu Tefsiri · ${surah?.sureAdi||''}</strong><div class="tafsir-text">${(entry?.tefsir||'Bu ayet için ayrı bir açıklama bulunamadı.').split('\n').map(p=>p.trim()?`<p>${p}</p>`:'').join('')}</div><small>Kaynak: Diyanet İşleri Başkanlığı, Kur’an Yolu Tefsiri</small>`;}catch(error){box.innerHTML=`<strong>Tefsir yüklenemedi</strong><p>${error.message}</p>`;}},true);

// Çekmece kapatıldığında her zaman ana sayfayı göster.
const drawer=document.querySelector('.app-drawer'),shade=document.querySelector('.drawer-shade');
function closeToHome(){document.body.classList.remove('drawer-open');showPage('home');}
if(drawer){const old=drawer.querySelector('.drawer-close'),fresh=old?.cloneNode(true);if(old&&fresh){old.replaceWith(fresh);fresh.onclick=closeToHome;}}
if(shade)shade.onclick=closeToHome;

// Eksik Esmâ anlamlarını tamamla.
const meanings={'Kâbıd':'Rızkı daraltan, ruhları teslim alan','Bâsıt':'Rızkı ve rahmeti genişleten','Hâfıd':'Dilediğini alçaltan','Râfi’':'Dilediğini yükselten','Muiz':'İzzet ve şeref veren','Müzil':'Dilediğini zillete düşüren','Semî’':'Her şeyi işiten','Basîr':'Her şeyi gören','Hakem':'Mutlak hükmeden','Adl':'Mutlak adalet sahibi','Latîf':'Lütfu ince ve sınırsız olan','Habîr':'Her şeyden haberdar olan','Halîm':'Cezada acele etmeyen','Azîm':'Azameti sonsuz olan','Gafûr':'Günahları çokça bağışlayan','Şekûr':'Az amele çok karşılık veren','Aliyy':'Yüceliği sonsuz olan','Kebîr':'Büyüklükte eşsiz olan','Hafîz':'Her şeyi koruyup gözeten','Mukît':'Her canlının rızkını veren','Hasîb':'Hesap gören ve kullarına yeten','Celîl':'Ululuk ve heybet sahibi','Kerîm':'İkramı ve cömertliği bol olan','Rakîb':'Her şeyi gözeten','Mucîb':'Dualara karşılık veren','Vâsi’':'Rahmeti ve ilmi her şeyi kuşatan','Hakîm':'Her işi hikmetli olan','Vedûd':'Kullarını seven ve sevdiren','Mecîd':'Şanı ve şerefi yüce olan','Bâis':'Ölüleri dirilten, peygamber gönderen','Şehîd':'Her şeye şahit olan','Hakk':'Varlığı ve sözü gerçek olan','Vekîl':'Kendisine güvenilip dayanılan','Kaviyy':'Kudreti sonsuz olan','Metîn':'Gücü sarsılmaz olan','Veliyy':'İnananların dostu ve yardımcısı','Hamîd':'Her türlü övgüye layık olan','Muhsî':'Her şeyi tek tek bilen ve sayan','Mübdi’':'Varlıkları ilk defa yaratan','Muîd':'Yarattıklarını yeniden dirilten','Muhyî':'Hayat veren','Mümît':'Ölümü yaratan','Hayy':'Diri ve hayat sahibi','Kayyûm':'Her şeyi ayakta tutan','Vâcid':'İstediğini bulan, hiçbir şeye muhtaç olmayan','Mâcid':'Şanı büyük ve cömert olan','Vâhid':'Tek ve eşsiz olan','Ahad':'Birliği bölünmeyen tek olan','Samed':'Her şeyin kendisine muhtaç olduğu','Kâdir':'Her şeye gücü yeten','Muktedir':'Kudreti her şeyi kuşatan','Mukaddim':'Dilediğini öne alan','Muahhir':'Dilediğini erteleyen','Evvel':'Başlangıcı olmayan','Âhir':'Sonu olmayan','Zâhir':'Varlığı açık ve delilleri belirgin olan','Bâtın':'Mahiyeti idrak edilemeyen','Vâlî':'Kâinatı yöneten','Müteâlî':'Her türlü eksiklikten yüce olan','Berr':'İyiliği ve ihsanı bol olan','Tevvâb':'Tövbeleri kabul eden','Müntakim':'Zulmedenleri adaletiyle cezalandıran','Afüv':'Günahları silip affeden','Raûf':'Şefkati çok olan','Mâlikü’l-mülk':'Mülkün gerçek sahibi','Zülcelâli ve’l-ikrâm':'Azamet ve ikram sahibi','Muksit':'Adaletle hükmeden','Câmi’':'Dilediklerini bir araya getiren','Ganî':'Hiçbir şeye muhtaç olmayan','Muğnî':'Zenginlik veren','Mâni’':'Dilediğine engel olan ve koruyan','Dârr':'Hikmetiyle zarar veren şeyleri yaratan','Nâfi’':'Fayda veren şeyleri yaratan','Nûr':'Âlemleri aydınlatan ve hidayet veren','Hâdî':'Doğru yola ileten','Bedî’':'Örneksiz ve benzersiz yaratan','Bâkî':'Varlığının sonu olmayan','Vâris':'Her şeyin gerçek sahibi olarak kalan','Reşîd':'Doğru yolu gösteren','Sabûr':'Cezada acele etmeyen, çok sabırlı'};
esma.forEach(item=>{if(meanings[item.name])item.meaning=meanings[item.name];});
})();
